import{_ as l,l as n,o as e,c as o,v as i,p as s,x as r,d,i as h,S as p}from"./chunks/framework.InCnrqk-.js";const P=JSON.parse('{"title":"随机游走与混合时间","description":"","frontmatter":{"title":"随机游走与混合时间","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/random-walk-mixing.md","filePath":"cs/random-walk-mixing.md","lastUpdated":1789023840000}'),m={name:"cs/random-walk-mixing.md"};function c(_,a,u,f,B,E){const t=n("Mermaid");return e(),o("div",null,[a[1]||(a[1]=i('<h1 id="随机游走与混合时间" tabindex="-1">随机游走与混合时间 <a class="header-anchor" href="#随机游走与混合时间" aria-label="Permalink to &quot;随机游走与混合时间&quot;">​</a></h1><div class="epigraph"><p>图上随机游走的分布趋向平稳；混合时间由谱隙或电导控制，抽样与连通判定共用这套。</p><footer>—— 据 Aldous–Fill；Levin, Peres and Wilmer, Markov Chains and Mixing Times；Motwani and Raghavan 整理</footer></div><p>上一课<a href="/cs/fingerprinting-freivalds">指纹</a>是一次随机映射。本课过程：顶点上的马尔可夫链。缺口是混合时间：多久接近 \\(\\pi\\)。不重写期望 DP 方程（那是吸收期望）。后课在线竞争比换模型。接<a href="/cs/graph-streaming">图流</a>只点名，本课随机访问图。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>正则无向图：\\(\\pi\\) 均匀。转移 \\(P=AD^{-1}\\)。谱隙 \\(1-\\lambda_2\\) 越大混合越快。电导 \\(\\Phi\\)（瓶颈）\\(\\le\\) 谱隙相关（Cheeger）。覆盖时间 \\(O(n^3)\\)（一般图 Rodeh/Aleliunas 等 \\(O(n m)\\) 级）。2-SAT 随机游走多项式点名。</p><p>缺口是混合，不是 Karger 收缩。</p><h3 id="不是物理布朗运动课" tabindex="-1">不是物理布朗运动课 <a class="header-anchor" href="#不是物理布朗运动课" aria-label="Permalink to &quot;不是物理布朗运动课&quot;">​</a></h3><p>离散图。连续时间链点名。不要写随机微分方程。</p><p><span class="marginnote">混合时间教材 Levin–Peres–Wilmer。Aldous 覆盖时间。后课在线算法没有平稳分布。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>要抽样：走 \\(t_{\\mathrm{mix}}\\) 步。要连通：覆盖或 UST（Wilson）点名。谱：幂法估 \\(\\lambda_2\\) 不在本课展开。</p>',11)),(e(),s(p,null,{default:r(()=>[h(t,{id:"mermaid-31",class:"mermaid",graph:"flowchart%20TD%0A%20%20G%5B%22%E5%9B%BE%22%5D%20--%3E%20RW%5B%22%E9%9A%8F%E6%9C%BA%E6%B8%B8%E8%B5%B0%22%5D%0A%20%20RW%20--%3E%20MIX%5B%22%E6%8E%A5%E8%BF%91%E5%B9%B3%E7%A8%B3%22%5D%0A%20%20MIX%20--%3E%20SMP%5B%22%E8%BF%91%E4%BC%BC%E5%9D%87%E5%8C%80%E7%82%B9%22%5D%0A"})]),fallback:r(()=>[...a[0]||(a[0]=[d(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=i('<p>懒惰链避免周期。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>总变差 \\(\\|P^t(x,\\cdot)-\\pi\\|_{\\mathrm{TV}}\\) 指数衰减，率谱隙。瓶颈集使混合慢（两团连一桥）。与期望到达：混合后才「忘起点」；到达期望可很长。与 expander：谱隙大，混合 \\(\\log n\\)。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不证 Cheeger 全不等式。不写 MCMC 统计物理。后课默认：随机游走混合由谱隙/电导管。下一课在线算法与竞争比。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>混合时间 = 忘起点、近平稳。</li><li>谱隙与电导；瓶颈则慢。</li><li>覆盖时间另一度量。</li><li>出处：Levin, Peres, Wilmer；Motwani–Raghavan。</li></ul>',7))])}const g=l(m,[["render",c]]);export{P as __pageData,g as default};
